// packages/server/src/mcp/grant.ts — no I/O, no imports from core.
export type Target =
  | { kind: 'all' }
  | { kind: 'group';  slug: string }
  | { kind: 'server'; slug: string }
  | { kind: 'smart';  groupSlug?: string };

export type Grant =
  | { kind: 'all' }
  | { kind: 'groups';  ids: readonly string[] }
  | { kind: 'servers'; ids: readonly string[] };

export interface Principal {
  readonly userId: string;
  readonly isAdmin: boolean;
  readonly credential: { type: 'apikey' | 'oauth'; id: string };
  readonly grant: Grant;
}

/** Full-containment rule. Pure. mcphub sseService.ts:228-302, lifted out of the transport. */
export function checkGrant(grant: Grant, scope: ResolvedScope): 'ok' | 'insufficient' {
  if (grant.kind === 'all') return 'ok';
  if (grant.kind === 'groups')
    return scope.groupIds.some(g => grant.ids.includes(g)) ? 'ok' : 'insufficient';
  // server-scoped key on a group/all route: EVERY member must be granted.
  return scope.serverIds.every(s => grant.ids.includes(s)) ? 'ok' : 'insufficient';
}

// packages/core/src/gateway.ts — owned by the engine subsystem. NO session concept, no HTTP.
export interface ResolvedScope {
  readonly targetKind: 'all' | 'group' | 'server' | 'smart';
  readonly serverIds: readonly string[];   // fully expanded, post-visibility
  readonly groupIds: readonly string[];    // [] unless the target is a group
}

export interface CallOpts {
  readonly signal: AbortSignal;                       // timeout OR client disconnect
  readonly onProgress?: (n: ProgressNotification) => void;
  readonly requestId: string;                         // for logs/traces/activity
}

export interface Gateway {
  /** null = the principal may not see this target. Server MUST render null as 404 not_found. */
  resolveTarget(p: Principal, t: Target): Promise<ResolvedScope | null>;

  listTools(s: ResolvedScope): Promise<Tool[]>;
  /** MUST re-resolve `name` against the same projection listTools uses, and MUST throw
   *  ToolUnavailableError with IDENTICAL text for a disabled tool and a nonexistent one.
   *  (mcphub CVE fix afcc72f; mcpService.ts:2654, :3388.) The server never pre-resolves. */
  callTool(s: ResolvedScope, name: string, args: unknown, o: CallOpts): Promise<CallToolResult>;

  listPrompts(s): Promise<Prompt[]>;
  getPrompt(s, name: string, args: unknown, o: CallOpts): Promise<GetPromptResult>;
  listResources(s): Promise<Resource[]>;
  listResourceTemplates(s): Promise<ResourceTemplate[]>;
  readResource(s, uri: string, o: CallOpts): Promise<ReadResourceResult>;
}

// packages/server/src/mcp/legacy.ts
import { Server } from '@modelcontextprotocol/sdk/server/index.js';
import { WebStandardStreamableHTTPServerTransport as Transport }
  from '@modelcontextprotocol/sdk/server/webStandardStreamableHttp.js';

export async function handleLegacy(c: Context, scope: ResolvedScope, gw: Gateway) {
  const server = new Server(
    { name: 'mcprouter', version: VERSION },
    { capabilities: { tools: {}, prompts: {}, resources: {} } },   // no sampling/elicitation
  );
  server.setRequestHandler(ListToolsRequestSchema, () => gw.listTools(scope).then(tools => ({ tools })));
  server.setRequestHandler(CallToolRequestSchema, async (req, extra) => {
    const release = await acquire(c.get('principal'));                 // limits.ts, may throw Busy
    try {
      return cap(await gw.callTool(scope, req.params.name, req.params.arguments, {
        signal: deadline(c),                                           // AbortSignal.any([...])
        onProgress: n => extra.sendNotification(n),
        requestId: c.get('requestId'),
      }));
    } finally { release(); }
  });
  // …prompts/get, resources/read, and the three list handlers, same shape.

  const transport = new Transport({ sessionIdGenerator: undefined });  // ← statelessness, one line
  await server.connect(transport);
  const res = await transport.handleRequest(c.req.raw);
  res.headers.set('X-Accel-Buffering', 'no');
  return res;
}

// packages/server/src/mcp/routes.ts
const mcp = new Hono<Env>();
mcp.use('*', requestId, bodyLimit({ maxSize: 4 * 1024 * 1024 }), mcpAuth);   // mcpAuth → 401 challenge
mcp.on(['GET', 'DELETE'], '/*', c => c.body(null, 405, { Allow: 'POST' }));

const post = (path: string, target: (c: Context) => Target) =>
  mcp.post(path, async c => {
    const p = c.get('principal');
    const scope = await gw.resolveTarget(p, target(c));
    if (!scope) return notFound(c);                                   // identical text, always
    if (checkGrant(p.grant, scope) !== 'ok') return insufficientScope(c);
    return handleLegacy(c, scope, gw);
  });

post('/',             ()  => ({ kind: 'all' }));
post('/g/:group',     (c) => ({ kind: 'group',  slug: slug(c, 'group') }));
post('/s/:server',    (c) => ({ kind: 'server', slug: slug(c, 'server') }));
post('/smart',        ()  => ({ kind: 'smart' }));
post('/smart/g/:group', (c)=> ({ kind: 'smart',  groupSlug: slug(c, 'group') }));
mcp.all('/*', c => notFound(c));

// slug() = SLUG.parse(c.req.param(k)) with zod; a parse failure is a 404, never a 400,
// so a malformed slug is indistinguishable from an invisible one.

// packages/server/src/mcp/auth.ts
export const mcpAuth: MiddlewareHandler<Env> = async (c, next) => {
  const t = c.req.header('authorization')?.match(/^Bearer (.+)$/i)?.[1];   // header ONLY
  if (!t) return challenge(c);                                            // 401 + WWW-Authenticate

  let p: Principal | null;
  if (t.startsWith('mcpr_')) {
    const { valid, key } = await auth.api.verifyApiKey({ body: { key: t } });
    p = valid && key ? { userId: key.userId, isAdmin: false,
                         credential: { type: 'apikey', id: key.id },
                         grant: parseGrant(key.metadata) } : null;        // rate limit: plugin's
  } else {
    const s = await auth.api.getMcpSession({ headers: c.req.raw.headers });
    p = s && s.audience === RESOURCE ? { userId: s.userId, isAdmin: false,
                         credential: { type: 'oauth', id: s.tokenId },
                         grant: scopesToGrant(s.scopes) } : null;         // RFC 8707 aud check
  }
  if (!p) return challenge(c);
  c.set('principal', p);
  await next();
};

const RESOURCE = `${PUBLIC_URL}/mcp`;
const challenge = (c: Context) => c.json({ error: 'unauthorized' }, 401, {
  'WWW-Authenticate':
    `Bearer resource_metadata="${PUBLIC_URL}/.well-known/oauth-protected-resource", scope="mcp"`,
});
const insufficientScope = (c: Context) => c.json({ error: 'forbidden' }, 403, {
  'WWW-Authenticate': `Bearer error="insufficient_scope", scope="mcp"`,
});

// packages/server/src/mcp/wellKnown.ts — one document, served at the root path and under /mcp/*.
const PRM = {
  resource: `${PUBLIC_URL}/mcp`,
  authorization_servers: [PUBLIC_URL],
  bearer_methods_supported: ['header'],
  scopes_supported: ['mcp'],
  resource_documentation: `${PUBLIC_URL}/docs/mcp`,
};
app.get('/.well-known/oauth-protected-resource',        c => c.json(PRM));
app.get('/.well-known/oauth-protected-resource/mcp/*',  c => c.json(PRM));

// packages/server/src/mcp/limits.ts
const inflight = new Map<string, number>();   // ponytail: per-process; ONE process by design.
                                              // upgrade: pg advisory lock keyed by principal if we replicate.
export async function acquire(p: Principal) {
  const k = p.credential.id;
  const n = inflight.get(k) ?? 0;
  if (n >= MCP_MAX_CONCURRENT) throw new HTTPException(429, { res: busy() });  // Retry-After: 1
  inflight.set(k, n + 1);
  return () => { const m = (inflight.get(k) ?? 1) - 1; m ? inflight.set(k, m) : inflight.delete(k); };
}

export const deadline = (c: Context) =>
  AbortSignal.any([c.req.raw.signal, AbortSignal.timeout(MCP_CALL_TIMEOUT_MS)]);

export function cap(r: CallToolResult): CallToolResult {
  const s = JSON.stringify(r);
  if (s.length <= MCP_MAX_RESULT_BYTES) return r;
  return { isError: r.isError, content: [{ type: 'text',
    text: `[mcprouter:truncated ${s.length} bytes, limit ${MCP_MAX_RESULT_BYTES}]` }] };
}
